def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    changed = True
    while changed:
        changed = False
        for r in range(h):
            for c in range(w):
                if out[r][c] != 6:
                    continue
                candidates = []
                for rr, cc in ((c, r), (31-r, c), (r, 31-c)):
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 6:
                        candidates.append(out[rr][cc])
                if candidates:
                    out[r][c] = candidates[0]
                    changed = True
    return out

